package com.airesumebuilder.feature.admin.service;import com.airesumebuilder.common.exception.ValidationException;import com.airesumebuilder.feature.admin.repository.AdminRepository;import java.time.Instant;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class AdminService{private static final Set<String>ROLES=Set.of("USER","ADMIN","RECRUITER"),STATUSES=Set.of("ACTIVE","INACTIVE","SUSPENDED");private final AdminRepository repository;public AdminService(AdminRepository r){repository=r;}@Transactional(readOnly=true)public UserPage users(int page,int size){int p=Math.max(0,page),s=Math.min(Math.max(1,size),100);return new UserPage(repository.users(s,p*s),p,s,repository.userCount());}@Transactional public UserView status(String admin,long id,ChangeRequest r){String value=upper(r.value());if(!STATUSES.contains(value))throw new ValidationException("Status must be ACTIVE, INACTIVE, or SUSPENDED.");guardSelf(admin,id,value,"ACTIVE");return repository.update(admin,id,"status",value,"USER_STATUS_CHANGED");}@Transactional public UserView role(String admin,long id,ChangeRequest r){String value=upper(r.value());if(!ROLES.contains(value))throw new ValidationException("Role must be USER, ADMIN, or RECRUITER.");guardSelf(admin,id,value,"ADMIN");return repository.update(admin,id,"role",value,"USER_ROLE_CHANGED");}@Transactional(readOnly=true)public List<ActionView>actions(int page,int size){int p=Math.max(0,page),s=Math.min(Math.max(1,size),100);return repository.actions(s,p*s);}private void guardSelf(String admin,long id,String value,String required){if(repository.email(id).equalsIgnoreCase(admin)&&!value.equals(required))throw new ValidationException("Administrators cannot remove their own access.");}private String upper(String v){return v==null?"":v.trim().toUpperCase(Locale.ROOT);}public record ChangeRequest(String value){}public record UserView(long id,String firstName,String lastName,String email,String role,String status,Instant createdAt){}public record UserPage(List<UserView>items,int page,int size,long total){}public record ActionView(long id,long adminUserId,Long targetUserId,String action,String details,Instant createdAt){} }
